package com.fakenewsdetector.service;
import com.fakenewsdetector.dto.AuthDtos.*; import com.fakenewsdetector.entity.*; import com.fakenewsdetector.repository.UserRepository; import com.fakenewsdetector.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService { private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt; public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} private UserView view(User u){return new UserView(u.getId(),u.getName(),u.getEmail(),u.getRole().name());}
 @Transactional public UserView register(Register r){String email=r.email().trim().toLowerCase();if(users.existsByEmailIgnoreCase(email))throw new IllegalArgumentException("Email is already registered.");return view(users.save(new User(r.name().trim(),email,encoder.encode(r.password()),Role.USER)));}
 public AuthView login(Login r){User u=users.findByEmailIgnoreCase(r.email().trim()).orElseThrow(()->new SecurityException("Invalid email or password."));if(!encoder.matches(r.password(),u.getPasswordHash()))throw new SecurityException("Invalid email or password.");return new AuthView(jwt.issue(u),view(u));} public UserView current(User u){return view(u);} }
